def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.1 * bins
    score = -np.abs(remaining - target_buffer)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.15 * bins
    score = -np.maximum(0.0, (remaining - target)) ** 1.5 - np.maximum(0.0, (target - remaining)) ** 1.5
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.15 * bins
    score = -np.exp((remaining - target_buffer) ** 2 / (bins + 1e-8))
    return np.where(remaining >= 0, score, -np.inf)

